structure.mermaidSource:
flowchart TD
  start["Início: Identificar T1 e T2"] --> dec_equiv{"T1 e T2 estão no mesmo patamar de sentido?"}
  dec_equiv -- "Sim" --> res_sinonimia["Sinonímia"]
  dec_equiv -- "Não" --> dec_tipo_de{"T1 é tipo de T2 OU T2 é tipo de T1?"}
  dec_tipo_de -- "Sim" --> dec_direcao{"Checar direcionalidade"}
  dec_direcao -- "T1 específico e T2 geral" --> res_hiponimia["Hiponímia"]
  dec_direcao -- "T1 geral e T2 específico" --> res_hiperonimia["Hiperonímia"]
  dec_tipo_de -- "Não" --> dec_tema{"Mesmo tema sem relação taxonômica?"}
  dec_tema -- "Sim" --> res_campo["Campo Semântico / Anáfora Associativa"]
  dec_tema -- "Não" --> res_distintas["Relações Lógicas Distintas"]

flowchart TD
  start["Início: Questão FGV de Relações Semânticas (A a E)"] --> proc_mapear["Mapear a Estrutura Semântica de Cada Par"]
  proc_mapear --> dec_espelhadas{"Existem pares com relações semânticas idênticas?"}
  dec_espelhadas -- "Sim (A = B ou D = E)" --> proc_anular["Aplicar a Equação Lógica: Eliminar em Bloco"]
  dec_espelhadas -- "Não (Pares heterogêneos)" --> dec_assimetria{"Restou uma única opção com relação hierárquica?"}
  proc_anular --> dec_assimetria
  dec_assimetria -- "Sim (Opção assimétrica isolada)" --> dec_ordem{"Respeita a ordem vetorial exigida no comando?"}
  dec_assimetria -- "Não (Nenhuma ou múltiplas opções)" --> res_reavaliar["Reavaliar Mapeamento Léxico das Opções"]
  dec_ordem -- "Sim (Vetor correto)" --> res_gabarito["Gabarito Validado: Opção Única com Vetor Correto"]
  dec_ordem -- "Não (Vetor invertido)" --> res_distrator_vetor["Distrator Invertido: Eliminar Alternativa"]

flowchart TD
  start["Início: Avaliação de Verbete de Dicionário (FGV)"] --> proc_isolar["Isolar Entrada e Hiperônimo de Abertura"]
  proc_isolar --> dec_ontologia{"Hiperônimo de abertura possui rigor taxonômico ontológico?"}
  dec_ontologia -- "Não (Erro categorial/taxonômico)" --> res_elim_ontologia["Eliminar Imediatamente: Falha Ontológica no Hiperônimo"]
  dec_ontologia -- "Sim (Taxonomia válida)" --> dec_amplitude{"Respeita a amplitude dicionarizada do vocábulo?"}
  dec_amplitude -- "Não (Restrição indevida a nicho)" --> res_elim_amplitude["Eliminar Opção: Redução Indevida da Amplitude"]
  dec_amplitude -- "Sim (Amplitude preservada)" --> dec_diferenca{"Diferença específica qualifica perfeitamente a entrada?"}
  dec_diferenca -- "Não (Diferença falha ou incompleta)" --> res_elim_diferenca["Eliminar Opção: Diferença Específica Incorreta"]
  dec_diferenca -- "Sim (Definição perfeita)" --> res_gabarito_verbete["Gabarito Validado: Verbete Lexicograficamente Preciso"]
